CREATE TYPE "AssetTrackingMode" AS ENUM ('Serialized','Quantity','Batch','Kit');
CREATE TYPE "AssetOwnershipType" AS ENUM ('BusinessOwned','ClientOwned','SupplierOwned','ThirdPartyOwned','Leased','Financed','PendingConfirmation');
CREATE TYPE "AssetCreationSource" AS ENUM ('ManualRegistration','ProcurementPurchase','SupplierHireIntake','ClientAssetIntake','StockImport','ManufacturingCompletion','AssetSplit','BatchReceipt','SystemIntegration','LegacyMigration');
CREATE TYPE "AssetLifecycleStatus" AS ENUM ('PendingIntake','Active','InInspection','InMaintenance','Quarantined','Damaged','Lost','Stolen','WrittenOff','Sold','ReturnedToOwner','Retired','Archived');
CREATE TYPE "AssetMovementType" AS ENUM ('Intake','PutAway','Relocation','Pick','Pack','Stage','Load','Dispatch','Deliver','Deploy','Return','Quarantine','MaintenanceTransfer','Disposal');
CREATE TYPE "AssetOperationStatus" AS ENUM ('Draft','Ready','InProgress','Exception','Completed','Cancelled');
CREATE TYPE "AssetReservationStatus" AS ENUM ('Draft','Reserved','Confirmed','Released','Fulfilled','Cancelled');
CREATE TYPE "AssetInspectionOutcome" AS ENUM ('Pass','PassWithNotes','Fail','Quarantine');
CREATE TYPE "AssetMaintenanceStatus" AS ENUM ('Draft','Approved','Scheduled','InProgress','AwaitingParts','Completed','Cancelled');
CREATE TYPE "AssetIncidentType" AS ENUM ('Damage','Loss','Missing','Theft','Failure');
CREATE TYPE "AssetIncidentStatus" AS ENUM ('Open','Investigating','RecoveryInProgress','Recovered','Resolved','WrittenOff');
CREATE TYPE "AssetDisposalStatus" AS ENUM ('Proposed','Approved','Executed','Cancelled');

CREATE TABLE "AssetDefinition" (
 "id" TEXT NOT NULL,"systemNumber" SERIAL NOT NULL,"organizationId" TEXT NOT NULL,"assetCode" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT,
 "classification" TEXT NOT NULL,"category" TEXT NOT NULL,"subcategory" TEXT,"trackingMode" "AssetTrackingMode" NOT NULL,"ownershipType" "AssetOwnershipType" NOT NULL,
 "ownershipPartyType" TEXT,"ownershipPartyId" TEXT,"unitOfMeasure" TEXT NOT NULL,"creationSource" "AssetCreationSource" NOT NULL,"originatingType" TEXT,"originatingId" TEXT,
 "family" TEXT,"variantAttributes" JSONB,"brand" TEXT,"model" TEXT,"manufacturer" TEXT,"internalSku" TEXT,"supplierSku" TEXT,"barcode" TEXT,"dimensions" TEXT,"weight" TEXT,
 "material" TEXT,"colour" TEXT,"finish" TEXT,"handlingRequirements" TEXT,"replacementValue" DOUBLE PRECISION,"capabilityTags" TEXT[] DEFAULT ARRAY[]::TEXT[],
 "quantityOnHand" DOUBLE PRECISION NOT NULL DEFAULT 0,"quantityUnavailable" DOUBLE PRECISION NOT NULL DEFAULT 0,"media" JSONB,"active" BOOLEAN NOT NULL DEFAULT true,
 "createdByUserId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"archivedAt" TIMESTAMP(3),
 CONSTRAINT "AssetDefinition_pkey" PRIMARY KEY ("id")
);
CREATE TABLE "AssetInstance" (
 "id" TEXT NOT NULL,"systemNumber" SERIAL NOT NULL,"organizationId" TEXT NOT NULL,"assetDefinitionId" TEXT NOT NULL,"operationalCode" TEXT NOT NULL,"manufacturerSerial" TEXT,
 "lifecycleStatus" "AssetLifecycleStatus" NOT NULL DEFAULT 'PendingIntake',"ownershipType" "AssetOwnershipType" NOT NULL,"creationSource" "AssetCreationSource" NOT NULL,
 "qrIdentity" TEXT,"barcodeIdentity" TEXT,"nfcIdentity" TEXT,"acquisitionDate" TIMESTAMP(3),"commissioningDate" TIMESTAMP(3),"warrantyExpiryDate" TIMESTAMP(3),
 "replacementValue" DOUBLE PRECISION,"conditionGrade" TEXT,"currentLocationId" TEXT,"currentCustodianType" TEXT,"currentCustodianId" TEXT,"controlStartDate" TIMESTAMP(3),
 "expectedControlEndDate" TIMESTAMP(3),"actualControlEndDate" TIMESTAMP(3),"sourceAgreementReference" TEXT,"parentInstanceId" TEXT,"createdByUserId" TEXT NOT NULL,
 "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"archivedAt" TIMESTAMP(3), CONSTRAINT "AssetInstance_pkey" PRIMARY KEY ("id")
);
CREATE TABLE "AssetBatch" ("id" TEXT NOT NULL,"systemNumber" SERIAL NOT NULL,"organizationId" TEXT NOT NULL,"assetDefinitionId" TEXT NOT NULL,"quantityReceived" DOUBLE PRECISION NOT NULL,"quantityBalance" DOUBLE PRECISION NOT NULL,"originReference" TEXT,"attributes" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "AssetBatch_pkey" PRIMARY KEY("id"));
CREATE TABLE "AssetKit" ("id" TEXT NOT NULL,"systemNumber" SERIAL NOT NULL,"organizationId" TEXT NOT NULL,"assetDefinitionId" TEXT NOT NULL,"name" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "AssetKit_pkey" PRIMARY KEY("id"));
CREATE TABLE "AssetKitMember" ("id" TEXT NOT NULL,"assetKitId" TEXT NOT NULL,"memberType" TEXT NOT NULL,"memberId" TEXT NOT NULL,"quantity" DOUBLE PRECISION NOT NULL DEFAULT 1,"effectiveFrom" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"effectiveTo" TIMESTAMP(3),"required" BOOLEAN NOT NULL DEFAULT true,CONSTRAINT "AssetKitMember_pkey" PRIMARY KEY("id"));
CREATE TABLE "AssetIdentityAudit" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"entityType" TEXT NOT NULL,"entityId" TEXT NOT NULL,"action" TEXT NOT NULL,"previousValue" JSONB,"newValue" JSONB,"reason" TEXT,"sourceAction" TEXT NOT NULL,"relatedType" TEXT,"relatedId" TEXT,"userId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AssetIdentityAudit_pkey" PRIMARY KEY("id"));
CREATE TABLE "AssetLocation" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"storageLocationId" TEXT,"parentLocationId" TEXT,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"locationType" TEXT NOT NULL,"barcode" TEXT,"qrIdentity" TEXT,"capacity" DOUBLE PRECISION,"capacityUnit" TEXT,"handlingRules" JSONB,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "AssetLocation_pkey" PRIMARY KEY("id"));
CREATE TABLE "AssetMovement" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"assetEntityType" TEXT NOT NULL,"assetEntityId" TEXT NOT NULL,"movementType" "AssetMovementType" NOT NULL,"quantity" DOUBLE PRECISION NOT NULL DEFAULT 1,"fromLocationId" TEXT,"toLocationId" TEXT,"fromCustodianType" TEXT,"fromCustodianId" TEXT,"toCustodianType" TEXT,"toCustodianId" TEXT,"eventId" TEXT,"referenceType" TEXT,"referenceId" TEXT,"reason" TEXT,"evidence" JSONB,"performedByUserId" TEXT NOT NULL,"occurredAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"recordedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AssetMovement_pkey" PRIMARY KEY("id"));
CREATE TABLE "AssetQrEvent" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"qrIdentity" TEXT NOT NULL,"assetEntityType" TEXT NOT NULL,"assetEntityId" TEXT NOT NULL,"action" TEXT NOT NULL,"locationId" TEXT,"eventId" TEXT,"deviceId" TEXT,"offlineRecordedAt" TIMESTAMP(3),"synchronizedAt" TIMESTAMP(3),"latitude" DOUBLE PRECISION,"longitude" DOUBLE PRECISION,"evidence" JSONB,"scannedByUserId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AssetQrEvent_pkey" PRIMARY KEY("id"));
CREATE TABLE "AssetReservation" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"eventId" TEXT NOT NULL,"requirementItemId" TEXT NOT NULL,"assetDefinitionId" TEXT NOT NULL,"assetInstanceId" TEXT,"quantity" DOUBLE PRECISION NOT NULL,"startDateTime" TIMESTAMP(3) NOT NULL,"endDateTime" TIMESTAMP(3) NOT NULL,"status" "AssetReservationStatus" NOT NULL DEFAULT 'Draft',"priority" INTEGER NOT NULL DEFAULT 0,"overrideReason" TEXT,"approvedByUserId" TEXT,"approvedAt" TIMESTAMP(3),"createdByUserId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "AssetReservation_pkey" PRIMARY KEY("id"));
CREATE TABLE "AssetOperation" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"eventId" TEXT,"operationType" TEXT NOT NULL,"status" "AssetOperationStatus" NOT NULL DEFAULT 'Draft',"sourceLocationId" TEXT,"targetLocationId" TEXT,"assignedTeamId" TEXT,"plannedStart" TIMESTAMP(3),"plannedEnd" TIMESTAMP(3),"actualStart" TIMESTAMP(3),"actualEnd" TIMESTAMP(3),"approvedByUserId" TEXT,"approvedAt" TIMESTAMP(3),"exceptionNotes" TEXT,"createdByUserId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "AssetOperation_pkey" PRIMARY KEY("id"));
CREATE TABLE "AssetOperationLine" ("id" TEXT NOT NULL,"assetOperationId" TEXT NOT NULL,"requirementItemId" TEXT,"assetEntityType" TEXT NOT NULL,"assetEntityId" TEXT NOT NULL,"quantityPlanned" DOUBLE PRECISION NOT NULL,"quantityCompleted" DOUBLE PRECISION NOT NULL DEFAULT 0,"sequence" INTEGER NOT NULL DEFAULT 0,"verificationMethod" TEXT,"evidence" JSONB,CONSTRAINT "AssetOperationLine_pkey" PRIMARY KEY("id"));
