CREATE TABLE "AssetIncident" ("id" TEXT NOT NULL,"systemNumber" SERIAL NOT NULL,"organizationId" TEXT NOT NULL,"eventId" TEXT,"assetEntityType" TEXT NOT NULL,"assetEntityId" TEXT NOT NULL,"incidentType" "AssetIncidentType" NOT NULL,"status" "AssetIncidentStatus" NOT NULL DEFAULT 'Open',"quantity" DOUBLE PRECISION NOT NULL DEFAULT 1,"occurredAt" TIMESTAMP(3) NOT NULL,"reportedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"locationId" TEXT,"custodianType" TEXT,"custodianId" TEXT,"description" TEXT NOT NULL,"evidence" JSONB,"estimatedLoss" DOUBLE PRECISION,"recoveryAmount" DOUBLE PRECISION,"liabilityPartyType" TEXT,"liabilityPartyId" TEXT,"resolutionNotes" TEXT,"reportedByUserId" TEXT NOT NULL,"resolvedByUserId" TEXT,"resolvedAt" TIMESTAMP(3),CONSTRAINT "AssetIncident_pkey" PRIMARY KEY("id"));
CREATE TABLE "AssetDisposal" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"assetEntityType" TEXT NOT NULL,"assetEntityId" TEXT NOT NULL,"status" "AssetDisposalStatus" NOT NULL DEFAULT 'Proposed',"disposalMethod" TEXT NOT NULL,"reason" TEXT NOT NULL,"proposedValue" DOUBLE PRECISION,"realisedValue" DOUBLE PRECISION,"proposedByUserId" TEXT NOT NULL,"proposedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"approvedByUserId" TEXT,"approvedAt" TIMESTAMP(3),"executedByUserId" TEXT,"executedAt" TIMESTAMP(3),"evidence" JSONB,CONSTRAINT "AssetDisposal_pkey" PRIMARY KEY("id"));
CREATE TABLE "AssetGovernanceException" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"exceptionType" TEXT NOT NULL,"severity" TEXT NOT NULL,"entityType" TEXT NOT NULL,"entityId" TEXT NOT NULL,"details" JSONB,"detectedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"resolvedAt" TIMESTAMP(3),"resolvedByUserId" TEXT,"resolutionNotes" TEXT,CONSTRAINT "AssetGovernanceException_pkey" PRIMARY KEY("id"));

